import {
  Card,
  CardContent,
  CardMedia,
  Typography,
  Grid,
  Container,
  Button,
  Box,
} from "@mui/material";

import { Link } from "react-router-dom";

import react_blog from "../../assets/images/react-blog.webp";
import mern_blog from "../../assets/images/mern-blog-image.webp";
import mui_blog from "../../assets/images/mui-blog-image.webp";

const blogs = [
  {
    id: 1,
    title: "Getting Started with React",
    description:
      "Learn the fundamentals of React and component-based architecture.",
    image: react_blog,
  },
  {
    id: 2,
    title: "Understanding MERN Stack",
    description:
      "A complete guide to MongoDB, Express, React, and Node.js.",
    image: mern_blog,
  },
  {
    id: 3,
    title: "Why Material UI is Great",
    description:
      "Explore how MUI helps build beautiful React applications quickly.",
    image: mui_blog,
  },
];

export default function Blog() {
  return (
    <Container
      maxWidth="lg"
      sx={{
        py: 8,
      }}
    >
      {/* Hero Section */}
      <Box
        sx={{
          textAlign: "center",
          mb: 8,
        }}
      >
        <Typography
          variant="h2"
          fontWeight={700}
          gutterBottom
        >
          Welcome to My Blog
        </Typography>

        <Typography
          variant="h6"
          color="text.secondary"
          sx={{
            maxWidth: "700px",
            mx: "auto",
          }}
        >
          Explore articles on React, MERN Stack,
          Material UI, and modern web development.
        </Typography>
      </Box>

      {/* Blog Cards */}
      <Grid container spacing={4}>
        {blogs.map((blog) => (
          <Grid
            item
            xs={12}
            sm={6}
            md={4}
            key={blog.id}
          >
            <Card
              sx={{
                height: "100%",
                display: "flex",
                flexDirection: "column",
                borderRadius: 4,
                overflow: "hidden",
                transition: "0.3s ease",
                boxShadow: 3,

                "&:hover": {
                  transform: "translateY(-8px)",
                  boxShadow: 6,
                },
              }}
            >
              {/* Blog Image */}
              <CardMedia
                component="img"
                image={blog.image}
                alt={blog.title}
                sx={{
                  height: 220,
                  objectFit: "cover",
                }}
              />

              {/* Blog Content */}
              <CardContent
                sx={{
                  flexGrow: 1,
                  p: 3,
                }}
              >
                <Typography
                  variant="h5"
                  fontWeight={700}
                  gutterBottom
                >
                  {blog.title}
                </Typography>

                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{
                    lineHeight: 1.7,
                  }}
                >
                  {blog.description}
                </Typography>
              </CardContent>

              {/* Read More Button */}
              <Box sx={{ p: 2 }}>
                <Button
                  component={Link}
                  to={`/blog/${blog.id}`}
                  variant="contained"
                  fullWidth
                  sx={{
                    borderRadius: 3,
                    py: 1.2,
                    fontWeight: 600,
                    textTransform: "none",
                    fontSize: "1rem",
                  }}
                >
                  Read More
                </Button>
              </Box>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Container>
  );
}
